func resourceVertexAITrainingPipelineDelete(d *schema.ResourceData, meta interface{}) error {
	if d.Get("deletion_policy").(string) == "PREVENT" {
		return fmt.Errorf("cannot destroy VertexAITrainingPipeline without setting deletion_policy=\"DELETE\" and running `terraform apply`")
	}
	if d.Get("deletion_policy").(string) == "ABANDON" {
		log.Printf("[DEBUG] deletion_policy set to \"ABANDON\", removing TrainingPipeline %q from Terraform state without deletion", d.Id())
		return nil
	}
	config := meta.(*transport_tpg.Config)
	userAgent, err := tpgresource.GenerateUserAgentString(d, config.UserAgent)
	if err != nil {
		return err
	}

	billingProject := ""

	project, err := tpgresource.GetProject(d, config)
	if err != nil {
		return fmt.Errorf("Error fetching project for TrainingPipeline: %s", err)
	}
	billingProject = project
	url, err := tpgresource.ReplaceVars(d, config, transport_tpg.BaseUrl(Product, config)+"projects/{{project}}/locations/{{region}}/trainingPipelines/{{name}}")
	if err != nil {
		return err
	}
	if strings.Contains(url, "{{region}}") {
		return fmt.Errorf("failed to qualify endpoint for a resource with a regionalized endpoint %s", url)
	}

	var obj map[string]interface{}

	// err == nil indicates that the billing_project value was found
	if bp, err := tpgresource.GetBillingProject(d, config); err == nil {
		billingProject = bp
	}

	headers := make(http.Header)
	// Cancel the TrainingPipeline first if it is still running or pending.
	// The Vertex AI TrainingPipeline API requires cancelling an active pipeline before deleting it.
	getRes, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   billingProject,
		RawURL:    url,
		UserAgent: userAgent,
		Headers:   headers,
	})
	if err != nil {
		return transport_tpg.HandleNotFoundError(err, d, fmt.Sprintf("VertexAITrainingPipeline %q", d.Id()))
	}

	state, _ := getRes["state"].(string)
	switch state {
	case "PIPELINE_STATE_QUEUED", "PIPELINE_STATE_PENDING", "PIPELINE_STATE_RUNNING", "PIPELINE_STATE_PAUSED":
		cancelUrl := fmt.Sprintf("%s:cancel", url)
		log.Printf("[DEBUG] Cancelling active TrainingPipeline %q (state: %s) before deletion", d.Id(), state)
		_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "POST",
			Project:   billingProject,
			RawURL:    cancelUrl,
			UserAgent: userAgent,
			Headers:   headers,
		})
		if err != nil && (!transport_tpg.IsGoogleApiErrorWithCode(err, 400) || !strings.Contains(err.Error(), "cannot be canceled")) {
			return fmt.Errorf("Error cancelling TrainingPipeline %q before deletion: %s", d.Id(), err)
		}
	}

	switch state {
	case "PIPELINE_STATE_QUEUED", "PIPELINE_STATE_PENDING", "PIPELINE_STATE_RUNNING", "PIPELINE_STATE_PAUSED", "PIPELINE_STATE_CANCELLING":
		waitFunc := func() (map[string]interface{}, error) {
			return transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: userAgent,
				Headers:   headers,
			})
		}
		err = transport_tpg.PollingWaitTime(waitFunc, func(pollRes map[string]interface{}, pollErr error) transport_tpg.PollResult {
			if pollErr != nil {
				return transport_tpg.ErrorPollResult(pollErr)
			}
			currState, _ := pollRes["state"].(string)
			switch currState {
			case "PIPELINE_STATE_CANCELLED", "PIPELINE_STATE_FAILED", "PIPELINE_STATE_SUCCEEDED":
				return transport_tpg.SuccessPollResult()
			default:
				return transport_tpg.PendingStatusPollResult(currState)
			}
		}, "Cancelling TrainingPipeline", d.Timeout(schema.TimeoutDelete), 1)
		if err != nil {
			return fmt.Errorf("Error waiting for TrainingPipeline %q to reach terminal state before deletion: %s", d.Id(), err)
		}
	}

	log.Printf("[DEBUG] Deleting TrainingPipeline %q", d.Id())
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "DELETE",
		Project:   billingProject,
		RawURL:    url,
		UserAgent: userAgent,
		Body:      obj,
		Timeout:   d.Timeout(schema.TimeoutDelete),
		Headers:   headers,
	})
	if err != nil {
		return transport_tpg.HandleNotFoundError(err, d, "TrainingPipeline")
	}

	// Derive location for use in REP endpoints
	endpointLocation := tpgresource.LocationFromId(d.Id())
	err = VertexAIOperationWaitTime(
		config, res, project, endpointLocation, "Deleting TrainingPipeline", userAgent,
		d.Timeout(schema.TimeoutDelete))

	if err != nil {
		return err
	}

	log.Printf("[DEBUG] Finished deleting TrainingPipeline %q: %#v", d.Id(), res)
	return nil
}

